import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

/* ============================================================
   0 · UTILIDADES
   ============================================================ */
const clamp = (v,a,b)=>Math.min(b,Math.max(a,v));
const lerp  = (a,b,t)=>a+(b-a)*t;
const smooth= t=>t*t*(3-2*t);
const rad   = d=>d*Math.PI/180;

function mergeGeos(list){
  const gs = list.map(g=>g.index?g.toNonIndexed():g);
  const total = gs.reduce((s,g)=>s+g.attributes.position.count,0);
  const out = new THREE.BufferGeometry();
  for(const [name,size] of [['position',3],['normal',3],['uv',2]]){
    const arr = new Float32Array(total*size);
    let off=0;
    for(const g of gs){
      const a=g.attributes[name];
      if(a){ arr.set(a.array.subarray(0,a.count*size), off); }
      off += g.attributes.position.count*size;
    }
    out.setAttribute(name, new THREE.BufferAttribute(arr,size));
  }
  return out;
}

/* ============================================================
   1 · TEXTURAS PROCEDURALES
   ============================================================ */
function cvs(size,draw){
  const c=document.createElement('canvas'); c.width=c.height=size;
  draw(c.getContext('2d'),size);
  const t=new THREE.CanvasTexture(c);
  t.colorSpace=THREE.SRGBColorSpace;
  t.wrapS=t.wrapT=THREE.RepeatWrapping;
  t.anisotropy=8;
  return t;
}
function rnd(seed){ let s=seed; return ()=> (s=(s*16807)%2147483647)/2147483647; }

/* azulejo:loor nazarí de 星形 (estrella de ocho puntas) */
function texAzulejo(){
  const t=cvs(512,(x,S)=>{
    x.fillStyle='#efe7d6'; x.fillRect(0,0,S,S);
    const r=rnd(7), n=8, c=S/n;
    const pal=['#1f6f8f','#2f7d4f','#b8442f','#c8a13c','#5c4b8a'];
    for(let i=0;i<n;i++)for(let j=0;j<n;j++){
      const ox=i*c, oy=j*c, col=pal[Math.floor(r()*pal.length)];
      x.fillStyle= r()>.55?'#f6f1e4':'#e6dcc6';
      x.fillRect(ox,oy,c,c);
      x.strokeStyle=col; x.lineWidth=2.4; x.strokeRect(ox+3,oy+3,c-6,c-6);
      x.save(); x.translate(ox+c/2,oy+c/2);
      x.fillStyle=col; x.globalAlpha=.85;
      x.beginPath();
      for(let k=0;k<16;k++){
        const a=k*Math.PI/8-Math.PI/2, rad2=(k%2?c*.12:c*.31);
        k?x.lineTo(Math.cos(a)*rad2,Math.sin(a)*rad2):x.moveTo(Math.cos(a)*rad2,Math.sin(a)*rad2);
      }
      x.closePath(); x.fill();
      x.globalAlpha=1; x.fillStyle='#fff';
      x.beginPath(); x.arc(0,0,c*.07,0,7); x.fill();
      x.restore();
    }
  });
  return t;
}
/* revoco encalado */
function texStucco(base){
  return cvs(256,(x,S)=>{
    x.fillStyle=base; x.fillRect(0,0,S,S);
    const r=rnd(21);
    for(let i=0;i<5200;i++){
      const a=r()*.16; x.fillStyle=r()>.5?`rgba(255,255,255,${a})`:`rgba(90,64,36,${a})`;
      x.fillRect(r()*S,r()*S,1+r()*2,1+r()*2);
    }
    for(let i=0;i<90;i++){ x.fillStyle='rgba(120,96,64,.05)'; x.fillRect(r()*S,0,1+r()*3,S); }
  });
}
/* teja árabe */
function texRoof(){
  return cvs(256,(x,S)=>{
    x.fillStyle='#8d4b30'; x.fillRect(0,0,S,S);
    const r=rnd(3);
    for(let row=0;row<8;row++){
      const y=row*S/8;
      for(let col=-1;col<9;col++){
        const xx=col*S/8 + (row%2?S/16:0);
        x.fillStyle=`hsl(${14+r()*8},${38+r()*14}%,${28+r()*12}%)`;
        x.beginPath(); x.ellipse(xx+S/16,y+S/16,S/16,S/9,0,Math.PI,0,true); x.fill();
        x.strokeStyle='rgba(40,20,10,.45)'; x.lineWidth=1.2; x.stroke();
      }
    }
  });
}
/* empedrado */
function texPaving(){
  return cvs(256,(x,S)=>{
    x.fillStyle='#8c8172'; x.fillRect(0,0,S,S);
    const r=rnd(11);
    for(let i=0;i<900;i++){
      const px=r()*S,py=r()*S,w=7+r()*7,h=6+r()*6;
      const l=40+r()*28;
      x.fillStyle=`hsl(${34+r()*16},${8+r()*10}%,${l}%)`;
      x.beginPath(); x.ellipse(px,py,w/2,h/2,r()*3,0,7); x.fill();
    }
  });
}
/* madera del techo (taracea) */
function texWood(){
  return cvs(256,(x,S)=>{
    x.fillStyle='#4a2c18'; x.fillRect(0,0,S,S);
    const r=rnd(5);
    for(let i=0;i<420;i++){
      x.strokeStyle=`rgba(${120+r()*70|0},${70+r()*40|0},30,.35)`;
      x.lineWidth=.6+r();
      x.beginPath(); const y=r()*S; x.moveTo(0,y); x.bezierCurveTo(S*.3,y+r()*8,S*.7,y-r()*8,S,y+r()*3); x.stroke();
    }
    for(let i=0;i<12;i++){
      x.strokeStyle='rgba(210,180,120,.18)'; x.lineWidth=1.4;
      x.beginPath(); x.arc(S/2,S/2,20+i*9,0,7); x.stroke();
    }
  });
}

/* ============================================================
   2 · MATERIALES
   ============================================================ */
const T = { az:texAzulejo(), stucco:texStucco('#e7d7b4'), stuccoW:texStucco('#f2ece0'),
            roof:texRoof(), pave:texPaving(), wood:texWood() };
function rep(t,rx,ry){ const c=t.clone(); c.needsUpdate=true; c.repeat.set(rx,ry); return c; }

const M = {
  earth : new THREE.MeshStandardMaterial({color:0xb79468,roughness:.97}),
  earthD: new THREE.MeshStandardMaterial({color:0x9c7a52,roughness:.97}),
  white : new THREE.MeshStandardMaterial({color:0xf0e6d4,roughness:.9}),
  wall  : new THREE.MeshStandardMaterial({color:0xd8c5a4,roughness:.93}),
  wall2 : new THREE.MeshStandardMaterial({color:0xc0a781,roughness:.95}),
  stone : new THREE.MeshStandardMaterial({color:0x9d9382,roughness:.92}),
  stone2: new THREE.MeshStandardMaterial({color:0x776f61,roughness:.9}),
  wood  : new THREE.MeshStandardMaterial({color:0x5b3a22,roughness:.8}),
  woodD : new THREE.MeshStandardMaterial({color:0x3a2415,roughness:.85}),
  gold  : new THREE.MeshStandardMaterial({color:0xc9a227,roughness:.32,metalness:.75}),
  iron  : new THREE.MeshStandardMaterial({color:0x2e2a26,roughness:.6,metalness:.5}),
  leaf  : new THREE.MeshStandardMaterial({color:0x4e7a3a,roughness:.95}),
  leaf2 : new THREE.MeshStandardMaterial({color:0x3d6430,roughness:.95}),
  cyp   : new THREE.MeshStandardMaterial({color:0x2f4d2c,roughness:.95}),
  grass : new THREE.MeshStandardMaterial({color:0x6d7d4a,roughness:1}),
  water : new THREE.MeshStandardMaterial({color:0x2f7f9e,roughness:.06,metalness:.5,transparent:true,opacity:.82}),
  glass : new THREE.MeshStandardMaterial({color:0x8fd0e8,roughness:.05,metalness:.2,transparent:true,opacity:.4}),
};
M.roof   = new THREE.MeshStandardMaterial({map:rep(T.roof,3,3),roughness:.88});
M.roofS  = new THREE.MeshStandardMaterial({map:rep(T.roof,1,1),roughness:.88});
M.dado   = new THREE.MeshStandardMaterial({map:rep(T.az,4,1),roughness:.35});
M.dadoW  = new THREE.MeshStandardMaterial({map:rep(T.az,2,1),roughness:.35});
M.pool   = new THREE.MeshStandardMaterial({map:rep(T.az,8,1),roughness:.3});
M.pave   = new THREE.MeshStandardMaterial({map:rep(T.pave,8,8),roughness:.95});
M.pave2  = new THREE.MeshStandardMaterial({map:rep(T.pave,20,20),roughness:.95});
M.stuccoT= new THREE.MeshStandardMaterial({map:rep(T.stucco,4,4),roughness:.95});
M.stuccoW= new THREE.MeshStandardMaterial({map:rep(T.stuccoW,3,3),roughness:.93});
M.ceil   = new THREE.MeshStandardMaterial({map:rep(T.wood,3,3),roughness:.7});

/* ============================================================
   3 · PRIMITIVAS DE CONSTRUCCIÓN
   ============================================================ */
const G = new THREE.Group();                       // mundo

function box(w,h,d,mat,x=0,y=0,z=0,ry=0){
  const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);
  m.position.set(x,y,z); m.rotation.y=ry; m.castShadow=true; m.receiveShadow=true; return m;
}
function cyl(rt,rb,h,seg,mat,x=0,y=0,z=0){
  const m=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,seg),mat);
  m.position.set(x,y,z); m.castShadow=true; m.receiveShadow=true; return m;
}
/* arco de herradura como agujero en un muro */
function archHole(cx,w,h){
  const a=w/2, R=a/Math.cos(rad(20)), yc=h-R;
  const p=new THREE.Path();
  p.moveTo(cx-a,0);
  p.lineTo(cx-a, yc-0.342*R);
  p.absarc(cx,yc,R,Math.PI+rad(20),-rad(20),true);
  p.lineTo(cx+a,0);
  p.closePath();
  return p;
}
/* muro con arcos (extrusión con huecos) */
function archWall(len,h,depth,openings,mat){
  const s=new THREE.Shape();
  s.moveTo(-len/2,0); s.lineTo(len/2,0); s.lineTo(len/2,h); s.lineTo(-len/2,h); s.closePath();
  for(const o of openings) s.holes.push(archHole(o.cx,o.w,o.h));
  const g=new THREE.ExtrudeGeometry(s,{depth,bevelEnabled:false,curveSegments:14});
  g.translate(0,0,-depth/2);
  const m=new THREE.Mesh(g,mat); m.castShadow=true; m.receiveShadow=true; return m;
}
/* columna esbelta con capitel y basa */
function columnGeo(h,r=0.14){
  const parts=[];
  const c=new THREE.CylinderGeometry(r*.88,r,h-0.34,10,1); c.translate(0,(h-0.34)/2+0.2,0);
  parts.push(c);
  const cap=new THREE.BoxGeometry(r*3.1,.2,r*3.1); cap.translate(0,h-.08,0); parts.push(cap);
  const bas=new THREE.BoxGeometry(r*2.9,.18,r*2.9); bas.translate(0,.09,0); parts.push(bas);
  const collar=new THREE.BoxGeometry(r*2.5,.14,r*2.5); collar.translate(0,h-.34,0); parts.push(collar);
  return mergeGeos(parts);
}
function column(h,r=0.14,mat=M.white,x=0,y=0,z=0){
  const m=new THREE.Mesh(columnGeo(h,r),mat); m.position.set(x,y,z);
  m.castShadow=true; m.receiveShadow=true; return m;
}
/* arquería: muro de arcos + columnas */
function arcade(len,h,bays,depth,mat=M.stuccoT,cols=true,r=0.14){
  const g=new THREE.Group(), bw=len/bays, op=[];
  for(let i=0;i<bays;i++) op.push({cx:-len/2+bw*(i+.5),w:bw*.66,h:h*.7});
  g.add(archWall(len,h,depth,op,mat));
  if(cols) for(let i=0;i<=bays;i++){
    const x=-len/2+bw*i;
    g.add(column(h*.7-.4,r,M.white,x,0,depth/2+.12));
    g.add(column(h*.7-.4,r,M.white,x,0,-depth/2-.12));
  }
  return g;
}
/* azotea con teja */
function roofBlock(w,d,h,mat=M.roof,y=0){
  const g=new THREE.Group();
  const slab=box(w+.7,.45,d+.7,M.stuccoT,0,y+.22,0); g.add(slab);
  const t=box(w,.55,d,mat,0,y+.72,0); g.add(t);
  return g;
}
/* torre rectangular */
function tower(w,d,h,mat=M.stuccoT,roof=true){
  const g=new THREE.Group();
  g.add(box(w,h,d,mat,0,h/2,0));
  g.add(box(w+.5,.6,d+.5,M.dadoW,0,h*.24,0));
  g.add(box(w+.7,.5,d+.7,M.stuccoW,0,h-.25,0));
  if(roof){ const r=roofBlock(w,d,0,M.roofS,h-.5); g.add(r); }
  return g;
}
/* torre circular (Torre de la Vela) */
function roundTower(r,h,lantern=true){
  const g=new THREE.Group();
  g.add(cyl(r,r*1.08,h,20,M.stuccoT,0,h/2,0));
  g.add(cyl(r*1.03,r*1.03,1.6,20,M.dadoW,0,h*.28,0));
  g.add(cyl(r*1.08,r*1.08,.6,20,M.stuccoW,0,h-.3,0));
  if(lantern){
    g.add(cyl(r*.62,r*.66,3.2,12,M.stuccoW,0,h+1.6,0));
    const roof=new THREE.Mesh(new THREE.ConeGeometry(r*.8,2.6,12),M.roofS);
    roof.position.y=h+4.5; roof.castShadow=true; g.add(roof);
    const bell=cyl(.55,.75,1.1,10,M.gold,0,h+.9,0); g.add(bell);
  }
  return g;
}
/* chimenea de tejado (torre de Comares) */
function merlon(x,y,z,w=1.6,h=1.2,d=1.6,mat=M.stuccoT){
  const g=new THREE.Group();
  g.add(box(w,h,d,mat,x,y+h/2,z));
  return g;
}

/* ============================================================
   4 · RELIEVE DEL TERRENO
   ============================================================ */
function gauss(x,z,cx,cz,sx,sz){ const dx=(x-cx)/sx,dz=(z-cz)/sz; return Math.exp(-(dx*dx+dz*dz)); }
function terrainH(x,z){
  let h=0;
  h += 11*gauss(x,z,-155,40,52,48);      // cerro de la Sabika (Alcazaba)
  h += 13*gauss(x,z,-140,-140,46,42);    // terraza del Generalife
  h -= 17*gauss(x,z,-40,-108,72,15);     // valle del Darro
  h +=  6*gauss(x,z,80,40,60,70);        // Silla del Moro
  h -=  2.5*gauss(x,z,-5,-15,70,60);     // explanada de los palacios
  h +=  3*gauss(x,z,-70,10,40,40);
  return h;
}

