/* --- 8.3 Palacio de Carlos V --- */
function buildCarlosV(){
  const g=new THREE.Group();
  const R=24, RIN=13.5;
  const s=new THREE.Shape();
  s.moveTo(-R,-R); s.lineTo(R,-R); s.lineTo(R,R); s.lineTo(-R,R); s.closePath();
  const hole=new THREE.Path(); hole.absarc(0,0,RIN,0,Math.PI*2,true);
  s.holes.push(hole);
  for(let lvl=0;lvl<2;lvl++){
    const geo=new THREE.ExtrudeGeometry(s,{depth:7,bevelEnabled:false,curveSegments:36});
    geo.rotateX(-Math.PI/2);
    const m=new THREE.Mesh(geo,lvl?M.stuccoW:M.stuccoT);
    m.position.y=lvl*7; m.castShadow=true; m.receiveShadow=true; g.add(m);
  }
  // columnas del patio circular
  for(let lvl=0;lvl<2;lvl++) for(let i=0;i<32;i++){
    const a=i/32*Math.PI*2;
    const c=cyl(.26,.3,6.4,12,M.stone,Math.cos(a)*(RIN-0.6),3.4+lvl*7,Math.sin(a)*(RIN-0.6));
    g.add(c);
    g.add(box(.9,.4,.9,M.stone,Math.cos(a)*(RIN-0.6),6.6+lvl*7,Math.sin(a)*(RIN-0.6)));
  }
  g.add(cyl(RIN,RIN,0.4,36,M.pave,0,0.2,0));
  // cornisa y cubierta
  g.add(box(R*2+1.6,1.1,R*2+1.6,M.stone2,0,14.6,0));
  const ring=new THREE.Mesh(new THREE.RingGeometry(RIN,Math.SQRT2*R,4,1),M.roof);
  ring.rotation.x=-Math.PI/2; ring.position.y=15.3; g.add(ring);
  // portada (sur)
  const por=arcade(14,7,4,3,M.stuccoW,true,0.3); por.position.set(0,0,R+1.2); g.add(por);
  g.add(box(16,1,4,M.dadoW,0,6.6,R+1.2));
  g.position.set(-80,0,50); G.add(g);
  planRect(-104,-56,26,74,'#9c9280');
}

