/* --- 8.8 Darro y puente --- */
function buildRiver(){
  const N=60, pos=[], idx=[];
  for(let i=0;i<=N;i++){
    const x=-230+i*6.5;
    const z=-106-7*Math.sin(x*0.012)+3*Math.cos(x*0.03);
    const y=terrainH(x,z)+0.25;
    pos.push(x,y,z, x,y,z-3.6);
  }
  for(let i=0;i<N;i++){
    const a=i*2,b=a+1,c=a+2,d=a+3;
    idx.push(a,c,b, b,c,d);
  }
  const geo=new THREE.BufferGeometry();
  geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));
  geo.setIndex(idx); geo.computeVertexNormals();
  const w=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color:0x2e6f8a,roughness:.15,metalness:.35,
    transparent:true,opacity:.85,side:THREE.DoubleSide}));
  w.receiveShadow=true; G.add(w);
  // puente de los Espinoles
