  pg.position.set(98,0,112); g.add(pg);
  // árboles
  for(let i=0;i<10;i++) tree(46+i*6,64+ (i%3)*4, 1);
  for(let i=0;i<8;i++) tree(44+i*7,132, 0.95);
  for(let i=0;i<6;i++) cyp(38,70+i*12,1.05);
  G.add(g);
}

/* ============================================================
   9 · VEGETACIÓN (instanciada)
   ============================================================ */
function buildVegetation(){
  // troncos
  const trunkG=new THREE.CylinderGeometry(0.22,0.34,3,6);
  trunkG.translate(0,1.5,0);
  const leavesG=new THREE.SphereGeometry(1.9,10,8);
  leavesG.translate(0,4.2,0);
  const bark=new THREE.MeshStandardMaterial({color:0x5a4432,roughness:.95});
  const leafM=new THREE.MeshStandardMaterial({color:0x4f7b38,roughness:.95,flatShading:true});
  if(TREES.length){
    const ti=new THREE.InstancedMesh(trunkG,bark,TREES.length);
    const li=new THREE.InstancedMesh(leavesG,leafM,TREES.length);
    const m=new THREE.Matrix4();
    TREES.forEach((t,i)=>{
      const y=terrainH(t.x,t.z);
      m.makeScale(t.s,t.s,t.s); m.setPosition(t.x,y,t.z); ti.setMatrixAt(i,m);
      m.makeScale(t.s*1.05,t.s*0.9,t.s*1.05); m.setPosition(t.x,y,t.z); li.setMatrixAt(i,m);
    });
    ti.castShadow=li.castShadow=true; ti.receiveShadow=li.receiveShadow=true;
    G.add(ti); G.add(li);
  }
  if(CYPS.length){
    const cg=new THREE.ConeGeometry(1.15,8,9); cg.translate(0,4,0);
    const ci=new THREE.InstancedMesh(cg,M.cyp,CYPS.length);
    const m=new THREE.Matrix4();
    CYPS.forEach((t,i)=>{
      const y=terrainH(t.x,t.z);
      m.makeScale(t.s,t.s,t.s); m.setPosition(t.x,y,t.z); ci.setMatrixAt(i,m);
    });
    ci.castShadow=true; G.add(ci);
  }
  if(HEDGES.length){
    const hg=new THREE.BoxGeometry(1,1,1);
    const hi=new THREE.InstancedMesh(hg,M.leaf2,HEDGES.length);
    const m=new THREE.Matrix4();
    HEDGES.forEach((t,i)=>{
      const y=terrainH(t.x,t.z);
      m.makeScale(t.w,t.h,t.d); m.setPosition(t.x,y+t.h/2,t.z); hi.setMatrixAt(i,m);
    });
    hi.castShadow=true; hi.receiveShadow=true; G.add(hi);
  }
}

