/* ============================================================
   6 · CURVA DEL RECORRIDO
   ============================================================ */
function pathH(x,z){
  return terrainH(x,z)+0.35+9*gauss(x,z,-30,-105,22,8.5);
}
const pts = NODES.map(([x,z])=>new THREE.Vector3(x,pathH(x,z),z));
const curve = new THREE.CatmullRomCurve3(pts,true,'centripetal',0.5);
const LEN = curve.getLength();
const SAMPLES=520;
const routePts=curve.getSpacedPoints(SAMPLES);

function distRoute(x,z){
  let best=1e9;
  for(let i=0;i<routePts.length;i+=2){
    const dx=routePts[i].x-x, dz=routePts[i].z-z;
    const d=dx*dx+dz*dz;
    if(d<best) best=d;
  }
  return Math.sqrt(best);
}

/* ============================================================
   7 · TERRENO
   ============================================================ */
function buildTerrain(){
  const SIZE=820, SEG=220;
  const geo=new THREE.PlaneGeometry(SIZE,SIZE,SEG,SEG);
  geo.rotateX(-Math.PI/2);
  const p=geo.attributes.position;
  const col=new Float32Array(p.count*3);
  const c=new THREE.Color();
  const grass=new THREE.Color(0x69794a), rock=new THREE.Color(0x8c7d63),
        sand=new THREE.Color(0xb59a72), dirt=new THREE.Color(0x94795a),
        dark=new THREE.Color(0x4a5b3c);
  for(let i=0;i<p.count;i++){
    const x=p.getX(i), z=p.getZ(i), y=terrainH(x,z);
    p.setY(i,y);
    const d=distRoute(x,z);
    if(d<4.2)      c.copy(sand);
    else if(d<8)   c.copy(sand).lerp(dirt,(d-4.2)/3.8);
    else if(y>6)   c.copy(grass).lerp(rock,clamp((y-6)/9,0,1));
    else if(y<-3)  c.copy(dark).lerp(rock,clamp((-y-3)/8,0,1));
    else           c.copy(grass).lerp(dark,clamp((Math.abs(x)-20)/220,0,.55));
    const n=Math.sin(x*0.31)*Math.cos(z*0.27)*0.045;
    c.offsetHSL(n*0.4,n*0.3,n);
    col[i*3]=c.r; col[i*3+1]=c.g; col[i*3+2]=c.b;
  }
  geo.setAttribute('color',new THREE.BufferAttribute(col,3));
  geo.computeVertexNormals();
  const m=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));
  m.receiveShadow=true;
  G.add(m);
}

/* ============================================================
   8 · CONSTRUCCIONES
   ============================================================ */
const PLAN=[];
function planRect(x0,x1,z0,z1,c){ PLAN.push({t:'r',v:[x0,x1,z0,z1],c:c||'#8b8272'}); }
function planCirc(x,z,r,c){ PLAN.push({t:'c',v:[x,z,r],c:c||'#8b8272'}); }

const TREES=[], CYPS=[], HEDGES=[];
function tree(x,z,s=1){ TREES.push({x,z,s}); }
function cyp(x,z,s=1){ CYPS.push({x,z,s}); }
function hedge(x,z,w,d,h=1.1){ HEDGES.push({x,z,w,d,h}); }

/* sector de anillo (para el patio circular de Carlos V) */
function ringSector(a0,a1,rOut,rIn,h,mat){
  const s=new THREE.Shape();
  s.moveTo(Math.cos(rad(a0))*rOut, Math.sin(rad(a0))*rOut);
  s.absarc(0,0,rOut,rad(a0),rad(a1),false);
  s.lineTo(Math.cos(rad(a1))*rIn, Math.sin(rad(a1))*rIn);
  s.absarc(0,0,rIn,rad(a1),rad(a0),true);
  s.closePath();
  const geo=new THREE.ExtrudeGeometry(s,{depth:h,bevelEnabled:false,curveSegments:44});
  geo.rotateX(-Math.PI/2);
  const m=new THREE.Mesh(geo,mat); m.castShadow=true; m.receiveShadow=true; return m;
}

/* --- 8.1 Plaza de los Alhambra --- */
function buildPlaza(){
  G.add(box(112,0.5,72,M.pave2,-13,0.02,110));
  planRect(-69,43,74,146,'#a89c88');
  // Puerta de las Granadas (sur)
  const gate=new THREE.Group();
  gate.add(box(8,7,3.4,M.stuccoW,0,3.5,0));
  gate.add(archWall(7,7,3.4,[{cx:0,w:2.6,h:4.6}],M.stuccoW));
  gate.add(box(8.4,.5,4,M.dado,0,7.1,0));
  for(let i=0;i<6;i++){
    gate.add(box(.9,.9,.2,M.dado,-3.5+i*1.4,7.7,1.8));
    gate.add(box(.9,.9,.2,M.dado,-3.5+i*1.4,7.7,-1.8));
  }
  gate.position.set(-6,0,143);
  G.add(gate);
  // pórtico de Comares (fachada norte de la plaza)
  const port=arcade(66,7.4,9,2.4,M.stuccoT,true,0.17);
  port.position.set(4,0,74);
  G.add(port);
  G.add(box(66,1.2,3.2,M.dadoW,4,0.6,74));
  // muralla norte de la plaza
  G.add(box(24,8,2.4,M.stuccoT,-46,4,74));
  G.add(box(24,.9,2.8,M.dadoW,-46,0.45,74));
  for(let i=0;i<7;i++) G.add(box(1.2,1.9,2.6,M.wood,-55+i*3.4,1.2,74));
  // iglesia de Santa María
  const ch=new THREE.Group();
  ch.add(box(11,7,22,M.stuccoW,0,3.5,0));
  ch.add(box(12,1.1,23,M.roofS,0,7.4,0));
  ch.add(box(4.5,2.4,4.5,M.stuccoW,0,9.2,-11));
  ch.add(box(1.2,2.4,.6,M.wood,0,8.6,-8.8));
  ch.position.set(34,0,68); G.add(ch);
  planRect(28,40,57,79,'#b0a596');
  // farolas
  for(let i=0;i<8;i++){
    const l=new THREE.Group();
    l.add(cyl(.1,.13,4.4,6,M.iron,0,2.2,0));
    const bulb=new THREE.Mesh(new THREE.SphereGeometry(.35,10,8),
      new THREE.MeshStandardMaterial({color:0xffe9b0,emissive:0xffcc66,emissiveIntensity:.5,roughness:.4}));
    bulb.position.y=4.6; l.add(bulb);
    l.position.set(-58+i*15,0,i%2?120:84);
    G.add(l);
  }
  for(let i=0;i<6;i++) tree(-52+i*18,130,0.9+(i%2)*0.2);
  for(let i=0;i<5;i++) tree(-60+i*20,88,0.85);
}

/* --- 8.2 Palacios Nazaríes --- */
function buildNasrid(){
  G.add(box(102,1.2,172,M.pave2,17,0.1,-14));
  planRect(-34,68,-100,72,'#9a8f7c');

  /* Patio de los Arrayanes (x -25..5, z -25..5) */
  const myr=new THREE.Group();
  myr.add(box(30,0.3,30,M.pave,-10,0.75,-10));
  const gN=arcade(30,7.6,5,2.4,M.stuccoT,true,0.16); gN.position.set(-10,0.9,-25); myr.add(gN);
  const gS=arcade(30,7.6,5,2.4,M.stuccoT,true,0.16); gS.position.set(-10,0.9,5);   myr.add(gS);
  const gW=arcade(30,7.6,5,2.4,M.stuccoT,true,0.16); gW.position.set(-25,0.9,-10); gW.rotation.y=Math.PI/2; myr.add(gW);
  const gE=arcade(30,7.6,5,2.4,M.stuccoT,true,0.16); gE.position.set(5,0.9,-10);   gE.rotation.y=Math.PI/2; myr.add(gE);
  myr.add(box(30,1.3,.35,M.dado,-10,1.55,-25.9));
  myr.add(box(30,1.3,.35,M.dado,-10,1.55,4.1));
  myr.add(box(17,0.55,1.6,M.stone,-10,0.9,-10));
  myr.add(box(16,0.2,1.0,M.pool,-10,1.12,-10));
  myr.add(box(16,0.12,1.0,M.water,-10,1.2,-10));
  for(let i=0;i<7;i++){ hedge(-19+i*3,-17,1.6,1.6,1.5); hedge(-19+i*3,-3,1.6,1.6,1.5); }
  for(let i=0;i<5;i++){ hedge(-23,-15+i*2.6,1.4,1.4,1.4); hedge(3,-15+i*2.6,1.4,1.4,1.4); }
  G.add(myr);
  planRect(-26,6,-26,6,'#b3a790');

  /* Torre de Comares (centro -10,-50) */
  const com=new THREE.Group();
  com.add(box(19,38,19,M.stuccoT,0,19,0));
  com.add(box(20,1.2,20,M.dadoW,0,9,0));
  com.add(box(20,1.2,20,M.dadoW,0,27,0));
  com.add(box(20.4,1,20.4,M.stuccoW,0,38,0));
  com.add(box(13,6,13,M.stuccoT,0,41.5,0));
  com.add(box(14,0.8,14,M.dadoW,0,45,0));
  const cr=new THREE.Mesh(new THREE.ConeGeometry(9.6,6,4),M.roofS);
  cr.position.y=48.5; cr.rotation.y=Math.PI/4; cr.castShadow=true; com.add(cr);
  for(let s=0;s<4;s++){
    const ang=s*Math.PI/2, cs=Math.cos(ang), sn=Math.sin(ang);
    for(let lvl=0;lvl<3;lvl++) for(let i=0;i<3;i++){
      const off=(i-1)*5.2;
      const px=cs*9.6+(s%2?off:0), pz=sn*9.6+(s%2?0:off);
      const w=box(1.3,2.6,.5,M.wood,px,13+lvl*11,pz);
      w.rotation.y=ang; com.add(w);
    }
  }
  const port=arcade(19,9,3,2.6,M.stuccoT,true,0.2); port.position.set(0,0,9.6); com.add(port);
  com.position.set(-10,0,-50); G.add(com);
  planRect(-20,0,-60,-40,'#a89a86');

  /* Mexuar (x -28..4, z -92..-76) */
  const mx=new THREE.Group();
  mx.add(box(32,10,16,M.stuccoT,0,5,0));
  mx.add(box(33,1.1,17,M.dadoW,0,7.6,0));
  mx.add(box(33,0.9,17,M.stuccoW,0,10.2,0));
  mx.add(box(30,1.2,14,M.roofS,0,11.2,0));
  const fac=archWall(32,10,1.6,[{cx:-11,w:4.4,h:7},{cx:-5.5,w:4.4,h:7},{cx:0,w:4.4,h:7},
    {cx:5.5,w:4.4,h:7},{cx:11,w:4.4,h:7}],M.stuccoT);
  fac.position.set(0,0,8.2); mx.add(fac);
  for(let i=0;i<5;i++) mx.add(cyl(.22,.26,7.2,10,M.stone,-11+i*5.5,3.6,8.9));
  const dome=new THREE.Mesh(new THREE.SphereGeometry(4.2,20,12,0,Math.PI*2,0,Math.PI/2),M.stuccoW);
  dome.position.set(6,11,0); dome.castShadow=true; mx.add(dome);
  mx.add(cyl(4.4,4.4,1.2,20,M.dadoW,6,10.9,0));
  mx.position.set(-12,0,-84); G.add(mx);
  planRect(-28,4,-92,-76,'#a89a86');

  /* Sala de los Abencerrajes (x 12..28, z -30..-14) */
  const ab=new THREE.Group();
  ab.add(box(16,0.4,16,M.pave,0,0.2,0));
  ab.add(box(16,9,1.6,M.stuccoT,0,4.5,-7.4));
  ab.add(box(16,9,1.6,M.stuccoT,0,4.5,7.4));
  const aw=archWall(16,9,1.6,[{cx:-4,w:3,h:6},{cx:4,w:3,h:6}],M.stuccoT);
  aw.position.set(-7.4,0,0); aw.rotation.y=Math.PI/2; ab.add(aw);
  const ae=archWall(16,9,1.6,[{cx:-4,w:3,h:6},{cx:4,w:3,h:6}],M.stuccoT);
  ae.position.set(7.4,0,0); ae.rotation.y=Math.PI/2; ab.add(ae);
  const muq=[];
  for(let r=0;r<4;r++){
    for(let i=-2;i<=2;i++) for(let j=-2;j<=2;j++){
      if(Math.abs(i)+Math.abs(j)>3-r*0.6) continue;
      const b=new THREE.BoxGeometry(1.5,0.5,1.5);
      b.translate(i*1.5,9+r*0.5,j*1.5); muq.push(b);
    }
  }
  const muqM=new THREE.Mesh(mergeGeos(muq),M.woodD);
  muqM.castShadow=true; ab.add(muqM);
  ab.add(box(14,0.4,14,M.ceil,0,10.6,0));
  ab.position.set(20,0,-22); G.add(ab);
  planRect(12,28,-30,-14,'#9d9280');

  /* Patio de los Leones (centro 45,-20) */
  const lio=new THREE.Group();
  lio.add(box(28,0.4,28,M.pave,0,0.2,0));
  const lN=arcade(28,8,4,2.6,M.stuccoT,true,0.18); lN.position.set(0,0,-14); lio.add(lN);
  const lS=arcade(28,8,4,2.6,M.stuccoT,true,0.18); lS.position.set(0,0,14);  lio.add(lS);
  const lW=arcade(28,8,4,2.6,M.stuccoT,true,0.18); lW.position.set(-14,0,0); lW.rotation.y=Math.PI/2; lio.add(lW);
  const lE=arcade(28,8,4,2.6,M.stuccoT,true,0.18); lE.position.set(14,0,0);  lE.rotation.y=Math.PI/2; lio.add(lE);
  lio.add(box(28,1.3,.35,M.dado,0,1.65,-13.1));
  lio.add(box(28,1.3,.35,M.dado,0,1.65,13.1));
  lio.add(cyl(4.6,4.6,0.9,12,M.stone,0,0.75,0));
  lio.add(cyl(4.2,4.2,0.25,12,M.pool,0,1.3,0));
  lio.add(cyl(4.2,4.2,0.12,12,M.water,0,1.4,0));
  lio.add(cyl(1.1,1.3,1.7,12,M.stone,0,2.1,0));
  lio.add(cyl(1.5,1.2,0.35,12,M.pool,0,3.05,0));
  for(let i=0;i<12;i++){
    const a=i/12*Math.PI*2;
    const l=box(1.5,1.0,1.1,M.stone,Math.cos(a)*4.0,1.7,Math.sin(a)*4.0);
    l.rotation.y=-a; lio.add(l);
    lio.add(cyl(.28,.3,.35,8,M.stone,Math.cos(a)*4.7,1.5,Math.sin(a)*4.7));
  }
  for(let s=0;s<4;s++){
    const ang=s*Math.PI/2, rm=new THREE.Group();
    rm.add(box(10,5,9,M.stuccoT,0,2.5,0));
    rm.add(box(11,0.8,10,M.dadoW,0,5.2,0));
    rm.add(box(11,0.7,10,M.roofS,0,6,0));
    rm.position.set(Math.cos(ang)*15.5,0,Math.sin(ang)*15.5);
    rm.rotation.y=ang+Math.PI/2;
    lio.add(rm);
  }
  lio.position.set(45,0,-20); G.add(lio);
  planRect(31,59,-34,-6,'#b0a48d');

  /* Mirador de Lindaraja (x 59..68) */
  const mir=new THREE.Group();
  mir.add(box(9,3,20,M.stone2,0,1.5,0));
  for(let i=0;i<5;i++){
    mir.add(cyl(.2,.24,4.2,10,M.white,-3.4+i*1.7,3.1,8.6));
    mir.add(cyl(.2,.24,4.2,10,M.white,-3.4+i*1.7,3.1,-8.6));
