/* --- 8.3 Palacio de Carlos V --- */
function buildCarlosV(){
  const g=new THREE.Group();
  const R=24, RIN=13.5;
  // anillo con dos vanos: este (0 grados) y sur (270 grados)
  const secA=ringSector(18,252,R,RIN,7,M.stuccoT); g.add(secA);
  const secB=ringSector(288,342,R,RIN,7,M.stuccoT); g.add(secB);
  const secC=ringSector(18,252,R,RIN,7,M.stuccoW); secC.position.y=7; g.add(secC);
  const secD=ringSector(288,342,R,RIN,7,M.stuccoW); secD.position.y=7; g.add(secD);
  // columnas del patio circular
  for(let lvl=0;lvl<2;lvl++) for(let i=0;i<32;i++){
    const a=i/32*Math.PI*2;
    const c=cyl(.26,.3,6.4,12,M.stone,Math.cos(a)*(RIN-0.7),3.4+lvl*7,Math.sin(a)*(RIN-0.7));
    g.add(c);
    g.add(box(.9,.4,.9,M.stone,Math.cos(a)*(RIN-0.7),6.6+lvl*7,Math.sin(a)*(RIN-0.7)));
  }
  g.add(cyl(RIN,RIN,0.4,36,M.pave,0,0.2,0));
  // cornisa y cubierta
  g.add(box(R*2+1.6,1.1,R*2+1.6,M.stone2,0,14.6,0));
  const rs=new THREE.Shape();
  rs.moveTo(-R-.8,-R-.8); rs.lineTo(R+.8,-R-.8); rs.lineTo(R+.8,R+.8); rs.lineTo(-R-.8,R+.8); rs.closePath();
  const rh=new THREE.Path(); rh.absarc(0,0,RIN,0,Math.PI*2,true); rs.holes.push(rh);
  const rgeo=new THREE.ExtrudeGeometry(rs,{depth:.6,bevelEnabled:false,curveSegments:44});
  rgeo.rotateX(-Math.PI/2);
  const roof=new THREE.Mesh(rgeo,M.roof); roof.position.y=15.3; roof.castShadow=true; g.add(roof);
  // portada sur
  const por=arcade(14,7,4,3,M.stuccoW,true,0.3); por.position.set(0,0,R+1.4); g.add(por);
  g.add(box(16,1,4,M.dadoW,0,6.6,R+1.4));
  // pórtico este (vano)
  for(let i=0;i<6;i++){
    const a=rad(-22+i*8.8), r=RIN+3;
    g.add(cyl(.26,.3,13,12,M.stone,Math.cos(a)*r,6.5,Math.sin(a)*r));
  }
  g.position.set(-80,0,50); G.add(g);
  planRect(-104,-56,26,74,'#9c9280');
}

