  const p=new THREE.Vector3(NODES[s.i][0],pathH(NODES[s.i][0],NODES[s.i][1]),NODES[s.i][1]);
  const grp=new THREE.Group();
  const spr=new THREE.Sprite(new THREE.SpriteMaterial({map:numberTexture(i+1),depthTest:true}));
  spr.scale.set(4.6,4.6,1); spr.position.y=5.2; grp.add(spr);
  const ped=new THREE.Mesh(new THREE.CylinderGeometry(1.5,1.7,.35,16),
    new THREE.MeshStandardMaterial({color:0x2a2f36,roughness:.8,emissive:0x6a4a18,emissiveIntensity:.4}));
  ped.position.y=.15; ped.receiveShadow=true; grp.add(ped);
  const ring=new THREE.Mesh(new THREE.TorusGeometry(1.9,.07,6,28),
    new THREE.MeshBasicMaterial({color:0xd9b26a,transparent:true,opacity:.6}));
  ring.rotation.x=-Math.PI/2; ring.position.y=.4; grp.add(ring);
  grp.position.copy(p);
  scene.add(grp);
  stopU.push({u:closestU(p),p,grp,spr});
});
function closestU(p){
  let best=1e9,bu=0;
  for(let i=0;i<1200;i++){
    const q=curve.getPointAt(i/1200);
    const d=q.distanceToSquared(p);
    if(d<best){best=d;bu=i/1200;}
  }
  return bu;
}

/* ============================================================
   12 · ETIQUETAS HTML
   ============================================================ */
const labelBox=document.getElementById('labels');
const LABELS=[];
function addLabel(text,pos,big=false,cls=''){
  const el=document.createElement('div');
  el.className='lbl'+(big?' big':'');
  el.innerHTML=cls?`<span class="idx">${cls}</span>${text}`:text;
  labelBox.appendChild(el);
  LABELS.push({el,p:pos.clone(),y:pos.y});
}
const SIGHT=[
 ['Alcazaba',-150,44,22],['Torre de la Vela',-172,20,26],['Palacio de Carlos V',-80,17,18],
 ['Puerta de la Justicia',-44,19,17],['Patio de los Arrayanes',-10,9,10],
 ['Torre de Comares',-10,50,8],['Mexuar',-12,13,7],['Sala de los Abencerrajes',20,11,7],
 ['Patio de los Leones',45,10,8],['Mirador de Lindaraja',64,8,10],
 ['Partal',-100,22,10],['Generalife',-133,22,12],['Puente de los Espinoles',-30,4,10],
 ['Jardines de la Alameda',72,8,10],['Iglesia de Santa María',34,12,9]
];
SIGHT.forEach(([t,x,y,z])=>addLabel(t,new THREE.Vector3(x,y,z),true));
STOPS.forEach((s,i)=>{
  const p=new THREE.Vector3(NODES[s.i][0],pathH(NODES[s.i][0],NODES[s.i][1])+6,NODES[s.i][1]);
  addLabel(s.t,p,false,String(i+1));
});
let labelsOn=true;

/* ============================================================
   13 · INTERFAZ
   ============================================================ */
const listEl=document.getElementById('list');
STOPS.forEach((s,i)=>{
  const li=document.createElement('li');
  li.innerHTML=`<span class="n">${i+1}</span><span class="t">${s.t}<span class="s">${s.s}</span></span>`;
  li.onclick=()=>goTo(i);
  listEl.appendChild(li);
});
const items=[...listEl.children];
const info=document.getElementById('info');
const iK=document.getElementById('i-k'), iT=document.getElementById('i-t'),
      iS=document.getElementById('i-s'), iP=document.getElementById('i-p'), iTip=document.getElementById('i-tip');
let current=-1;
function showStop(i,speak=true){
  if(i===current) return;
  current=i;
  const s=STOPS[i];
  items.forEach((el,k)=>el.classList.toggle('on',k===i));
  info.classList.add('swap');
  setTimeout(()=>{
    iK.textContent=`Parada ${i+1} de ${STOPS.length}`;
    iT.textContent=s.t; iS.textContent=s.s; iP.textContent=s.p; iTip.textContent='▸ '+s.tip;
    info.classList.remove('swap');
  },260);
  if(speak&&voiceOn&&window.speechSynthesis){
    try{
      const u=new SpeechSynthesisUtterance(`${s.t}. ${s.p}`);
      u.lang='es-ES'; u.rate=.96; u.pitch=1;
      speechSynthesis.cancel(); speechSynthesis.speak(u);
    }catch(e){}
  }
}

/* controles */
let playing=true, spd=1, view='guia', voiceOn=false, tod=17.6;
const playBtn=document.getElementById('play');
playBtn.onclick=()=>{ playing=!playing; playBtn.textContent=playing?'❚❚ Pausa':'▶ Reproducir';
  playBtn.classList.toggle('on',playing); };
document.getElementById('restart').onclick=()=>{ u=0; lastU=0; };
const spdBtn=document.getElementById('spd');
const SPEEDS=[.5,1,2,4];
spdBtn.onclick=()=>{ spd=SPEEDS[(SPEEDS.indexOf(spd)+1)%SPEEDS.length]; spdBtn.textContent=spd+'×'; };
document.querySelectorAll('[data-view]').forEach(b=>{
  b.onclick=()=>{
    document.querySelectorAll('[data-view]').forEach(x=>x.classList.remove('on'));
    b.classList.add('on'); view=b.dataset.view;
    controls.enabled=(view==='libre');
    if(view==='libre'){ controls.target.copy(curPos); }
  };
});
const todEl=document.getElementById('tod'), clockEl=document.getElementById('clock');
todEl.oninput=()=>{ tod=parseFloat(todEl.value);
  const h=Math.floor(tod), m=Math.round((tod-h)*60);
  clockEl.textContent=`${String(h).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`; };
document.getElementById('lbl').onclick=function(){ labelsOn=!labelsOn; this.classList.toggle('on',labelsOn);
  if(!labelsOn) LABELS.forEach(l=>l.el.style.display='none'); };
document.getElementById('voice').onclick=function(){ voiceOn=!voiceOn; this.classList.toggle('on',voiceOn);
  if(!voiceOn&&window.speechSynthesis) speechSynthesis.cancel(); };

/* salto a una parada */
let tween=null;
function goTo(i){
  const target=stopU[i].u;
  tween={from:u,to:target,t:0,dur:1.6};
  showStop(i);
}

/* ============================================================
   14 · SOL Y HORA DEL DÍA
   ============================================================ */
const LAMPS=[];
scene.traverse(o=>{ if(o.material&&o.material.emissive&&o.material.emissiveIntensity>0.4&&o.material.emissive.getHex()===0xffcc66) LAMPS.push(o.material); });
const cTop=new THREE.Color(), cBot=new THREE.Color();
const PAL=[
 [0.0,0x070c1a,0x0d1626],[0.12,0x2a3f6b,0xe08a4e],[0.26,0x4b86c4,0xd7e6ee],
 [0.62,0x4b86c4,0xd7e6ee],[0.76,0x2f3f6d,0xef9450],[0.88,0x141c33,0x2b3550],[1.0,0x070c1a,0x0d1626]
];
function skyPal(t,out){
  for(let i=0;i<PAL.length-1;i++){
    if(t>=PAL[i][0]&&t<=PAL[i+1][0]){
      const f=(t-PAL[i][0])/(PAL[i+1][0]-PAL[i][0]||1);
      out.top.setHex(PAL[i][1]).lerp(new THREE.Color(PAL[i+1][1]),f);
      out.bot.setHex(PAL[i][2]).lerp(new THREE.Color(PAL[i+1][2]),f);
      return;
    }
  }
}
function updateSun(h){
  const dayT=clamp((h-6)/14,0,1);
  const az=Math.PI*dayT, el=Math.sin(dayT*Math.PI)*1.12;
  const dir=new THREE.Vector3(Math.cos(az)*Math.cos(el),Math.sin(el),0.45*Math.sin(el)+0.22).normalize();
  const dayF=clamp(Math.sin(el)*3.4,0,1);
  sun.position.copy(dir).multiplyScalar(340).add(new THREE.Vector3(-45,0,-30));
  sun.target.position.set(-45,0,-30);
  sun.intensity=0.25+3.3*dayF;
  sun.color.setHex(0xff9c4e).lerp(new THREE.Color(0xfff4e2),clamp(el/0.9,0,1));
  skyPal(clamp((h-6)/14,0,1),{top:cTop,bot:cBot});
  skyU.top.value.copy(cTop); skyU.bot.value.copy(cBot);
  skyU.sun.value.copy(dir); skyU.sunCol.value.copy(sun.color);
  hemi.intensity=0.28+0.85*dayF;
  hemi.color.copy(cTop).lerp(new THREE.Color(0xffffff),.35);
  hemi.groundColor.setHex(0x3a3226).lerp(new THREE.Color(0x6b5a44),dayF);
  amb.intensity=0.1+0.14*dayF;
  starMat.opacity=clamp(0.85-dayF*1.6,0,0.85);
  scene.fog.color.copy(cBot);
  scene.fog.density=0.0016+ (1-dayF)*0.0008;
  renderer.toneMappingExposure=0.95+0.22*dayF;
  LAMPS.forEach(m=>{ m.emissiveIntensity=0.35+1.5*(1-dayF); });
}

/* ============================================================
   15 · MINIMAPA
   ============================================================ */
const mm=document.getElementById('mmap'), mx=mm.getContext('2d');
const MB={x0:-196,x1:106,z0:-186,z1:158};
const MS=Math.min(mm.width/(MB.x1-MB.x0),mm.height/(MB.z1-MB.z0));
const MOX=(mm.width-(MB.x1-MB.x0)*MS)/2, MOZ=(mm.height-(MB.z1-MB.z0)*MS)/2;
const mX=x=>MOX+(x-MB.x0)*MS, mZ=z=>MOZ+(MB.z1-z)*MS;
function drawMap(){
  mx.clearRect(0,0,mm.width,mm.height);
  // río
  mx.strokeStyle='rgba(80,150,190,.55)'; mx.lineWidth=2;
  mx.beginPath();
  for(let x=-230;x<=140;x+=8){
    const z=-104-3*Math.sin(x*.008);
    x===-230?mx.moveTo(mX(x),mZ(z)):mx.lineTo(mX(x),mZ(z));
  }
  mx.stroke();
  // masas de edificio
  PLAN.forEach(p=>{
    mx.fillStyle=p.c; mx.strokeStyle='rgba(0,0,0,.45)'; mx.lineWidth=.6;
    mx.beginPath();
    if(p.t==='r') mx.rect(mX(p.v[0]),mZ(p.v[3]),(p.v[1]-p.v[0])*MS,(p.v[3]-p.v[2])*MS);
    else mx.arc(mX(p.v[0]),mZ(p.v[1]),p.v[2]*MS,0,7);
    mx.fill(); mx.stroke();
  });
  // trazado
  mx.strokeStyle='rgba(255,190,90,.95)'; mx.lineWidth=1.8; mx.setLineDash([4,3]);
  mx.beginPath();
  routePts.forEach((p,i)=> i?mx.lineTo(mX(p.x),mZ(p.z)):mx.moveTo(mX(p.x),mZ(p.z)));
  mx.stroke(); mx.setLineDash([]);
  // paradas
  stopU.forEach((s,i)=>{
    mx.fillStyle=(i===current)?'#f5d79a':'rgba(217,178,106,.85)';
    mx.beginPath(); mx.arc(mX(s.p.x),mZ(s.p.z),(i===current)?4.6:3,0,7); mx.fill();
    mx.fillStyle='#101214'; mx.font='bold 7px sans-serif'; mx.textAlign='center'; mx.textBaseline='middle';
    mx.fillText(String(i+1),mX(s.p.x),mZ(s.p.z)+.4);
  });
  // viajero
  const p=curPos;
  mx.save();
  mx.translate(mX(p.x),mZ(p.z));
  mx.rotate(Math.atan2(dir3.x,dir3.z));
  mx.fillStyle='#fff'; mx.beginPath();
  mx.moveTo(0,-6); mx.lineTo(4,4); mx.lineTo(0,1.5); mx.lineTo(-4,4); mx.closePath(); mx.fill();
  mx.restore();
  // norte
  mx.fillStyle='rgba(255,255,255,.55)'; mx.font='9px sans-serif'; mx.textAlign='center';
  mx.fillText('N',mm.width-12,14);
  mx.strokeStyle='rgba(255,255,255,.5)'; mx.beginPath();
  mx.moveTo(mm.width-12,18); mx.lineTo(mm.width-12,30); mx.stroke();
  mx.beginPath(); mx.moveTo(mm.width-12,16); mx.lineTo(mm.width-15,22); mx.lineTo(mm.width-9,22); mx.closePath();
  mx.fillStyle='rgba(255,255,255,.6)'; mx.fill();
}

/* ============================================================
   16 · BUCLE DE ANIMACIÓN
   ============================================================ */
let u=0, lastU=0, lastT=performance.now(), curStop=-1;
const curPos=new THREE.Vector3(), dir3=new THREE.Vector3(), tmpV=new THREE.Vector3();
const TOUR=175;

function frame(now){
  requestAnimationFrame(frame);
  const dt=Math.min((now-lastT)/1000,.05); lastT=now;

  // avance del recorrido
  if(tween){
    tween.t+=dt;
    const k=clamp(tween.t/tween.dur,0,1);
    let d=tween.to-tween.from;
    if(d>0.5) d-=1; if(d<-0.5) d+=1;
    u=(tween.from+d*smooth(k)+1)%1;
    if(k>=1){ tween=null; lastU=u; }
  } else if(playing){
    u=(u+dt*spd/TOUR)%1;
  }
  lastU=u;

  // posición y dirección
  curve.getPointAt(u,curPos);
  curve.getTangentAt(u,dir3); dir3.y=0; dir3.normalize();
  traveler.position.copy(curPos);
  halo.rotation.z+=dt*1.2;
  orb.scale.setScalar(1+Math.sin(now*0.004)*0.07);

  // detección de paradas
  let best=-1,bd=1e9;
  stopU.forEach((s,i)=>{
    let d=Math.abs(s.u-u); if(d>0.5) d=1-d;
    if(d<bd){bd=d;best=i;}
  });
  if(best>=0&&bd<0.0045&&best!==curStop){ curStop=best; showStop(best); }

  // cámara
  const fwd=dir3.clone();
  const side=new THREE.Vector3(-fwd.z,0,fwd.x);
  let want=new THREE.Vector3(), look=new THREE.Vector3();
  if(view==='guia'){
    want.copy(curPos).addScaledVector(fwd,-17).add(new THREE.Vector3(0,8.5,0));
    look.copy(curPos).addScaledVector(fwd,7).add(new THREE.Vector3(0,2,0));
  } else if(view==='cine'){
    want.copy(curPos).addScaledVector(side,30).addScaledVector(fwd,-12).add(new THREE.Vector3(0,17,0));
    look.copy(curPos).addScaledVector(fwd,9).add(new THREE.Vector3(0,1,0));
  } else if(view==='pea'){
    want.copy(curPos).add(new THREE.Vector3(0,1.75,0));
    look.copy(curPos).addScaledVector(fwd,12).add(new THREE.Vector3(0,1.75,0));
  }
  if(view!=='libre'){
    const k=1-Math.pow(0.0015,dt);
    camera.position.lerp(want,k);
    tmpV.copy(look); camera.lookAt(tmpV);
  } else {
    controls.update();
  }

  // tubería animada
  dash.offset.x=(-now*0.00009)%1;
  glowMat.opacity=0.10+0.05*Math.sin(now*0.002);

  // etiquetas
  if(labelsOn){
    for(const L of LABELS){
      tmpV.copy(L.p).project(camera);
      if(tmpV.z>1||tmpV.z<-1||Math.abs(tmpV.x)>1.2||Math.abs(tmpV.y)>1.2){ L.el.style.display='none'; continue; }
      L.el.style.display='block';
      L.el.style.left=((tmpV.x*0.5+0.5)*innerWidth)+'px';
      L.el.style.top=((-tmpV.y*0.5+0.5)*innerHeight)+'px';
      L.el.style.opacity=String(clamp(1.6-Math.abs(tmpV.z)*1.2,.25,1));
    }
  }

  updateSun(tod);
  drawMap();

  // progreso
  const pr=Math.round(u*100);
  document.getElementById('prog').textContent=pr+'%';

  renderer.render(scene,camera);
}

/* ============================================================
   17 · ARRANQUE
   ============================================================ */
function init(){
  buildTerrain();
  buildPlaza();
  buildNasrid();
  buildCarlosV();
  buildJusticia();
  buildAlcazaba();
  buildPartal();
  buildGeneralife();
  buildRiver();
  buildAlameda();
  buildVegetation();
  scene.add(G);
  showStop(0,false);
  addEventListener('resize',()=>{
    camera.aspect=innerWidth/innerHeight; camera.updateProjectionMatrix();
    renderer.setSize(innerWidth,innerHeight);
  });
  updateSun(tod);
  requestAnimationFrame(frame);
  setTimeout(()=>{ document.getElementById('load').classList.add('gone'); },700);
}
try{ init(); }
catch(err){
  console.error(err);
  document.getElementById('err').textContent='Error al iniciar: '+err.message;
}
</script>
</body>
</html>

