function gauss(x,z,cx,cz,sx,sz){ const dx=(x-cx)/sx,dz=(z-cz)/sz; return Math.exp(-(dx*dx+dz*dz)); }
function flatMask(x,z,x0,x1,z0,z1,m=22){
  const dx=Math.max(x0-x,0,x-x1), dz=Math.max(z0-z,0,z-z1);
  return 1-smooth(clamp(Math.hypot(dx,dz)/m,0,1));
}
function terrainH(x,z){
  let h=0;
  h += 11*gauss(x,z,-155,40,52,48);      // cerro de la Sabika (Alcazaba)
  h += 13*gauss(x,z,-140,-132,50,60);    // terraza del Generalife
  h -=  9*gauss(x,z,-40,-106,72,14);     // valle del Darro
  h +=  6*gauss(x,z,80,40,60,70);        // Silla del Moro
  h -=  1.2*gauss(x,z,-5,-15,70,60);     // leve hundimiento del palacio
  h +=  3*gauss(x,z,-70,10,40,40);
  // explanadas: explanada de los palacios + plaza, y patio de Carlos V
  h=lerp(h,0,flatMask(x,z,-74,74,-106,152,24));
  h=lerp(h,0,flatMask(x,z,-112,-52,18,86,20));
  return h;
}

