cat > /tmp/opencode/test5.mjs <<'EOF'
import pw from '/opt/node22/lib/node_modules/playwright/index.js';
const { chromium } = pw;
const browser = await chromium.launch({ executablePath:'/usr/bin/google-chrome',
  args:['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--no-sandbox'] });
const page = await browser.newPage({ viewport:{width:600,height:400} });
await page.goto('file:///tmp/opencode/dbg.html');
await page.waitForTimeout(9000);
const res = await page.evaluate(()=>{
  const D=window.__D, THREE=D.THREE;
  // ocultar tubo, resplandor, viajero y marcadores
  const hide=[];
  D.scene.traverse(o=>{ if(o.isMesh && (o.material===undefined)) {} });
  const tubeMat=new THREE.MeshBasicMaterial();
  const hidden=[];
  D.scene.traverse(o=>{
    if(o.isMesh && o.geometry && o.geometry.type==='TubeGeometry'){ hidden.push(o); o.visible=false; }
    if(o.isSprite) { hidden.push(o); o.visible=false; }
    if(o.isMesh && o.geometry && o.geometry.type==='CylinderGeometry' && o.material.emissive) { /* nada */ }
  });
  const rc=new THREE.Raycaster();
  const bad=[];
  const N=360;
  for(let i=0;i<N;i++){
    const u=i/N;
    const p=D.curve.getPointAt(u);
    rc.set(new THREE.Vector3(p.x,p.y+120,p.z), new THREE.Vector3(0,-1,0));
    rc.far=300;
    const hits=rc.intersectObjects(D.scene.children,true);
    // el primer impacto por encima de la ruta
    const h=hits.find(h=>h.point.y<p.y+30);
    if(h && h.point.y>p.y+1.2){
      const near=D.stopU.map((s,k)=>({k,d:Math.hypot(s.p.x-p.x,s.p.z-p.z),t:s.t})).sort((a,b)=>a.d-b.d)[0];
      bad.push({u:+u.toFixed(3),x:+p.x.toFixed(1),z:+p.z.toFixed(1),py:+p.y.toFixed(2),hy:+h.point.y.toFixed(2),
                obj:h.object.geometry?.type, near:near.t, dn:+near.d.toFixed(0)});
    }
  }
  hidden.forEach(o=>o.visible=true);
  // agrupar por proximity
  return {total:bad.length, sample:bad.slice(0,40)};
});
console.log('puntos enterrados:',res.total);
res.sample.forEach(b=>console.log(JSON.stringify(b)));
await browser.close();
EOF
