import pw from '/opt/node22/lib/node_modules/playwright/index.js';
const { chromium } = pw;
const browser = await chromium.launch({ executablePath:'/usr/bin/google-chrome',
  args:['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--no-sandbox'] });
const page = await browser.newPage({ viewport:{width:1280,height:800} });
const errs=[]; page.on('pageerror',e=>errs.push('PAGEERROR: '+e.message));
page.on('console',m=>{ if(m.type()==='error') errs.push('CONSOLE: '+m.text()); });
await page.goto('file:///tmp/bench-ws/ollama_minimax-m3/A3D/alhambra-3d.html');
await page.waitForTimeout(10000);

const st = await page.evaluate(()=>({
  sub: document.getElementById('sub').textContent,
  load: document.getElementById('load').classList.contains('gone'),
  list: document.querySelectorAll('#stops li').length,
  labels: document.querySelectorAll('#labels .lbl').length,
  mm: (()=>{ const c=document.getElementById('mmap'); const x=c.getContext('2d');
             const d=x.getImageData(0,0,c.width,c.height).data; let n=0;
             for(let i=0;i<d.length;i+=4) if(d[i+3]>10) n++; return n; })()
}));
console.log('estado inicial', JSON.stringify(st));

// clic en la parada 10 (Mirador de Lindaraja)
await page.evaluate(()=>document.querySelectorAll('#stops li')[9].click());
await page.waitForTimeout(6000);
const st2 = await page.evaluate(()=>({
  title: document.getElementById('i-t').textContent,
  kicker: document.getElementById('i-k').textContent,
  active: document.querySelector('#stops li.on')?.textContent.slice(0,40),
  prog: document.getElementById('prog').textContent
}));
console.log('tras clic', JSON.stringify(st2));

// hora del día
await page.evaluate(()=>{ const s=document.getElementById('tod'); s.value=7.2;
  s.dispatchEvent(new Event('input')); });
await page.waitForTimeout(2500);
const clock = await page.evaluate(()=>document.getElementById('clock').textContent);
console.log('reloj', clock);
await page.screenshot({path:'/tmp/opencode/f_amanecer.png'});

await page.evaluate(()=>{ const s=document.getElementById('tod'); s.value=19.6;
  s.dispatchEvent(new Event('input')); });
