import pw from '/opt/node22/lib/node_modules/playwright/index.js';
const { chromium } = pw;
const browser = await chromium.launch({ executablePath:'/usr/bin/google-chrome',
  args:['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--no-sandbox'] });
const page = await browser.newPage({ viewport:{width:800,height:600} });
await page.goto('file:///tmp/opencode/dbg.html');
await page.waitForTimeout(9000);
const res = await page.evaluate(()=>{
  const D=window.__D, THREE=D.THREE;
  const MESHES=[]; D.scene.traverse(o=>{ if(o.isMesh) MESHES.push(o); });
  const rc=new THREE.Raycaster();
  const out=[];
  for(let i=0;i<D.stopU.length;i++){
    const s=D.stopU[i];
    // posicion de camara 'guia' y 'cine' teoricas
    const p=s.p, f=Math.atan2(0,1);
    const out2={i, t:D.STOPS[i].t, ok:true, msgs:[]};
    const cams={
      guia:[p.x, p.y+8.5, p.z+17],
      cine:[p.x+30, p.y+17, p.z-12],
      pea:[p.x, p.y+1.75, p.z]
    };
    for(const [k,c] of Object.entries(cams)){
      const o=new THREE.Vector3(c[0],c[1],c[2]);
      rc.set(o,new THREE.Vector3(0,1,0)); rc.far=60;
      const hits=rc.intersectObjects(MESHES,false).filter(h=>h.distance>0.2);
      if(hits.length){ out2.ok=false; out2.msgs.push(k+' techo a '+hits[0].distance.toFixed(1)+'m'); }
      rc.set(o,new THREE.Vector3(0,-1,0)); rc.far=60;
      const hits2=rc.intersectObjects(MESHES,false).filter(h=>h.distance>0.2);
      if(hits2.length && hits2[0].distance<1.5){ out2.ok=false; out2.msgs.push(k+' suelo a '+hits2[0].distance.toFixed(1)+'m'); }
    }
    out.push(out2);
  }
  return out;
});
res.forEach(r=>console.log((r.ok?'OK  ':'!!  ')+String(r.i+1).padStart(2)+' '+r.t+(r.msgs.length?'  -> '+r.msgs.join(' | '):'')));
await browser.close();
EOF
